		/// Return SaleDocDetail based on primary key parameters default of MA_SaleDocDetail if not found with Async method
		/// </summary>
        /// <remarks>Prefered to use GetSaleDocDetail with selector parameter</remarks>
		
		/// <param name="saleDocId">It links the sale document lines with the head of the same document.</param>
		
		/// <param name="line">It indicates the position in the grid of each document line. It is, together with SaleDocId, the table key.</param>
		
		/// <param name="default">default value returned if no value is found</param>
		/// <returns>An istance of MA_SaleDocDetail or default if not found</returns>
        /// <exception cref="InvalidOperationException">Throw when result has more than one element.</exception>
        [Obsolete("Prefered to use GetSaleDocDetail with selector parameter")]
        public Task<MA_SaleDocDetail> GetSaleDocDetailAsync(Int32 saleDocId,Int16 line,
												   MA_SaleDocDetail @default = default)
			=> ResultAsync(Query(saleDocId,line), @default);

		#endregion 
		
    }

